from __future__ import annotations

import base64
import csv
import gzip
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUT_DIR = ROOT / "public" / "data"
PAYLOAD_B64 = """"""

CSV_FIELDS = [
    "regime", "regionType", "batch", "announcementDate", "sequence", "institutionName", "englishName",
    "serviceContent", "serviceChannel", "recordNumber", "province", "city", "serviceTypes", "year",
    "sourceTitle", "sourceUrl", "sourceFile", "note",
]


def write_json(path: Path, payload) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")


def write_csv(path: Path, records: list[dict]) -> None:
    with path.open("w", encoding="utf-8-sig", newline="") as file:
        writer = csv.DictWriter(file, fieldnames=CSV_FIELDS)
        writer.writeheader()
        for record in records:
            row = {field: record.get(field, "") for field in CSV_FIELDS}
            row["serviceTypes"] = "、".join(record.get("serviceTypes", []))
            writer.writerow(row)


def build() -> None:
    payload = json.loads(gzip.decompress(base64.b64decode(PAYLOAD_B64)).decode("utf-8"))
    write_json(OUT_DIR / "financial-records.json", payload["records"])
    write_json(OUT_DIR / "financial-facets.json", payload["facets"])
    write_json(OUT_DIR / "financial-stats.json", payload["stats"])
    write_json(OUT_DIR / "financial-sources.json", payload["sources"])
    write_json(OUT_DIR / "financial-laws.json", payload["laws"])
    write_csv(OUT_DIR / "financial-records.csv", payload["records"])
    print(json.dumps(payload["stats"], ensure_ascii=False))


if __name__ == "__main__":
    build()
